 681→    setModalError(null);
 682→
 683→    const fd = new FormData();
 684→    fd.set("intent", "submit");
 685→    fd.set("title", newTitle.trim());
 686→    fd.set("description", newDescription.trim());
 687→    fd.set("category", newCategory);
 688→    submitFetcher.submit(fd, { method: "POST" });
 689→  }, [newTitle, newDescription, newCategory, submitFetcher]);
 690→
 691→  const handleStatusChange = useCallback(
 692→    (id: string, newStatus: string) => {
 693→      const fd = new FormData();
