 707→      return next;
 708→    });
 709→  }, []);
 710→
 711→  const handleCloseModal = useCallback(() => {
 712→    setModalOpen(false);
 713→    setNewTitle("");
 714→    setNewDescription("");
 715→    setNewCategory("General");
 716→    setModalError(null);
 717→  }, []);
 718→
 719→  const handleOpenEdit = useCallback((feature: FeatureRequestRecord) => {
 720→    setEditId(feature.id);
 721→    setEditTitle(feature.title);
 722→    setEditDescription(feature.description);
 723→    setEditCategory(feature.category);
