 744→    fd.set("category", editCategory);
 745→    editFetcher.submit(fd, { method: "POST" });
 746→  }, [editId, editTitle, editDescription, editCategory, editFetcher]);
 747→
 748→  const handleCloseEditModal = useCallback(() => {
 749→    setEditModalOpen(false);
 750→    setEditId("");
 751→    setEditTitle("");
 752→    setEditDescription("");
 753→    setEditCategory("General");
 754→    setEditModalError(null);
 755→  }, []);
 756→
 757→  // ------------------------------------------------------------------
 758→  // Tabs config
