1193→              label="Category"
1194→              options={CATEGORY_OPTIONS}
1195→              value={newCategory}
1196→              onChange={setNewCategory}
1197→              helpText="Choose the category that best fits your request."
1198→            />
1199→          </BlockStack>
1200→        </Modal.Section>
1201→      </Modal>
1202→
1203→      {/* ---- Edit Feature Request Modal ---- */}
1204→      <Modal
1205→        open={editModalOpen}
1206→        onClose={handleCloseEditModal}
