1214→      >
1215→        <Modal.Section>
1216→          <BlockStack gap="400">
1217→            {editModalError && (
1218→              <Banner tone="critical" onDismiss={() => setEditModalError(null)}>
1219→                {editModalError}
1220→              </Banner>
1221→            )}
1222→            <TextField
1223→              label="Title"
1224→              value={editTitle}
1225→              onChange={setEditTitle}
1226→              placeholder="e.g. Export ZIP codes to CSV"
1227→              autoComplete="off"
1228→              maxLength={150}
1229→              showCharacterCount
1230→              helpText="Keep it short and descriptive."
1231→            />
1232→            <TextField
1233→              label="Description"
1234→              value={editDescription}
1235→              onChange={setEditDescription}
1236→              placeholder="Describe the feature and why it would be valuable..."
1237→              autoComplete="off"
1238→              multiline={4}
1239→              maxLength={MAX_DESCRIPTION_LENGTH}
1240→              showCharacterCount
1241→              helpText="The more context you provide, the better we can understand your needs."
1242→            />
1243→            <Select
1244→              label="Category"
1245→              options={CATEGORY_OPTIONS}
1246→              value={editCategory}
1247→              onChange={setEditCategory}
1248→              helpText="Choose the category that best fits your request."
1249→            />
1250→          </BlockStack>
1251→        </Modal.Section>
1252→      </Modal>
1253→    </Page>
