 160→function formatDate(d: string | Date): string {
 161→  return new Date(d).toLocaleDateString("en-US", {
 162→    month: "short",
 163→    day: "numeric",
 164→    year: "numeric",
 165→  });
 166→}
 167→
 168→function truncateText(text: string, maxChars: number): string {
 169→  if (text.length <= maxChars) return text;
 170→  return text.slice(0, maxChars).trimEnd() + "\u2026";
 171→}
