 173→// ---------------------------------------------------------------------------
 174→// Loader
 175→// ---------------------------------------------------------------------------
 176→
 177→export const loader = async ({ request }: LoaderFunctionArgs) => {
 178→  const { session } = await authenticate.admin(request);
 179→  const shop = session.shop;
 180→
 181→  const [features, myVotes] = await Promise.all([
 182→    db.featureRequest.findMany({
 183→      orderBy: { votesCount: "desc" },
 184→      take: 500,
 185→    }),
 186→    db.featureVote.findMany({
 187→      where: { shop },
 188→      select: { featureRequestId: true },
 189→    }),
 190→  ]);
 191→
 192→  const votedIds = myVotes.map((v) => v.featureRequestId);
 193→
 194→  const stats = {
 195→    total: features.length,
 196→    under_review: features.filter((f) => f.status === "under_review").length,
 197→    planned: features.filter((f) => f.status === "planned").length,
 198→    in_progress: features.filter((f) => f.status === "in_progress").length,
 199→    done: features.filter(
 200→      (f) => f.status === "done" || f.status === "shipped",
 201→    ).length,
 202→  };
 203→
 204→  const isAdmin = shop === ADMIN_SHOP;
 205→
 206→  return { features, votedIds, shop, stats, isAdmin };
 207→};
