 209→// ---------------------------------------------------------------------------
 210→// Action
 211→// ---------------------------------------------------------------------------
 212→
 213→export const action = async ({
 214→  request,
 215→}: ActionFunctionArgs): Promise<ActionResult> => {
 216→  const { session } = await authenticate.admin(request);
 217→  const shop = session.shop;
 218→  const isAdmin = shop === ADMIN_SHOP;
 219→  const formData = await request.formData();
 220→  const intent = String(formData.get("intent") ?? "");
 221→
 222→  try {
 223→    switch (intent) {
 224→      case "submit": {
 225→        const title = String(formData.get("title") ?? "").trim();
 226→        const description = String(formData.get("description") ?? "").trim();
 227→        const rawCategory = String(formData.get("category") ?? "General").trim();
 228→        const category = VALID_CATEGORIES.has(rawCategory) ? rawCategory : "General";
 229→
 230→        if (!title || !description) {
 231→          return { error: "Title and description are required." };
 232→        }
 233→        if (title.length > 150) {
 234→          return { error: "Title must be 150 characters or fewer." };
 235→        }
 236→        if (description.length > MAX_DESCRIPTION_LENGTH) {
 237→          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
 238→        }
 239→
 240→        // Per-shop submission limit
 241→        const existingCount = await db.featureRequest.count({ where: { shop } });
 242→        if (existingCount >= MAX_REQUESTS_PER_SHOP) {
 243→          return { error: `You can submit up to ${MAX_REQUESTS_PER_SHOP} feature requests. Delete an existing one to submit a new one.` };
 244→        }
 245→
 246→        await db.featureRequest.create({
 247→          data: { title, description, category, shop },
 248→        });
 249→
 250→        return { success: true, intent: "submit" };
 251→      }
 252→
 253→      case "vote": {
 254→        const featureId = String(formData.get("featureId") ?? "").trim();
 255→        if (!featureId) return { error: "Feature ID is required." };
 256→
 257→        const feature = await db.featureRequest.findUnique({
 258→          where: { id: featureId },
 259→        });
 260→        if (!feature) return { error: "Feature request not found." };
 261→
 262→        const existing = await db.featureVote.findUnique({
 263→          where: {
 264→            featureRequestId_shop: { featureRequestId: featureId, shop },
 265→          },
 266→        });
 267→
 268→        let voted: boolean;
 269→
 270→        if (existing) {
 271→          await db.featureVote.delete({ where: { id: existing.id } });
 272→          // Atomic decrement
 273→          const updated = await db.featureRequest.update({
 274→            where: { id: featureId },
 275→            data: { votesCount: { decrement: 1 } },
 276→          });
 277→          // Ensure count doesn't go below 0
 278→          if (updated.votesCount < 0) {
 279→            await db.featureRequest.update({
 280→              where: { id: featureId },
 281→              data: { votesCount: 0 },
 282→            });
 283→          }
 284→          voted = false;
 285→          const finalCount = Math.max(0, updated.votesCount);
 286→          return { success: true, intent: "vote", featureId, newCount: finalCount, voted };
 287→        } else {
 288→          await db.featureVote.create({
 289→            data: { featureRequestId: featureId, shop },
 290→          });
 291→          // Atomic increment
 292→          const updated = await db.featureRequest.update({
 293→            where: { id: featureId },
 294→            data: { votesCount: { increment: 1 } },
 295→          });
 296→          voted = true;
 297→          return { success: true, intent: "vote", featureId, newCount: updated.votesCount, voted };
 298→        }
 299→      }
 300→
 301→      case "delete": {
 302→        const deleteId = String(formData.get("id") ?? "").trim();
 303→        if (!deleteId) return { error: "Feature ID is required." };
 304→
 305→        const toDelete = await db.featureRequest.findUnique({
 306→          where: { id: deleteId },
 307→        });
 308→        if (!toDelete) return { error: "Feature request not found." };
 309→
 310→        // Admin can delete any, regular users only their own
 311→        if (!isAdmin && toDelete.shop !== shop) {
 312→          return { error: "You can only delete your own feature requests." };
 313→        }
 314→
 315→        await db.featureRequest.delete({ where: { id: deleteId } });
 316→        return { success: true, intent: "delete" };
 317→      }
 318→
 319→      case "edit": {
 320→        const editId = String(formData.get("id") ?? "").trim();
 321→        const editTitle = String(formData.get("title") ?? "").trim();
 322→        const editDescription = String(formData.get("description") ?? "").trim();
 323→        const rawEditCategory = String(formData.get("category") ?? "General").trim();
 324→        const editCategory = VALID_CATEGORIES.has(rawEditCategory) ? rawEditCategory : "General";
 325→
 326→        if (!editId) return { error: "Feature ID is required." };
 327→        if (!editTitle || !editDescription) {
 328→          return { error: "Title and description are required." };
 329→        }
 330→        if (editTitle.length > 150) {
 331→          return { error: "Title must be 150 characters or fewer." };
 332→        }
 333→        if (editDescription.length > MAX_DESCRIPTION_LENGTH) {
 334→          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
 335→        }
 336→
 337→        const toEdit = await db.featureRequest.findUnique({ where: { id: editId } });
 338→        if (!toEdit) return { error: "Feature request not found." };
 339→
 340→        if (!isAdmin && toEdit.shop !== shop) {
 341→          return { error: "You can only edit your own feature requests." };
 342→        }
 343→
 344→        await db.featureRequest.update({
 345→          where: { id: editId },
 346→          data: { title: editTitle, description: editDescription, category: editCategory },
 347→        });
 348→
 349→        return { success: true, intent: "edit" };
 350→      }
 351→
 352→      case "update-status": {
 353→        if (!isAdmin) {
 354→          return { error: "Only the app admin can change request statuses." };
 355→        }
 356→
 357→        const statusId = String(formData.get("id") ?? "").trim();
 358→        const newStatus = String(formData.get("status") ?? "").trim();
 359→
 360→        if (!statusId) return { error: "Feature ID is required." };
 361→        if (!VALID_STATUSES.has(newStatus)) {
 362→          return { error: "Invalid status value." };
 363→        }
 364→
 365→        const toUpdate = await db.featureRequest.findUnique({
 366→          where: { id: statusId },
 367→        });
 368→        if (!toUpdate) return { error: "Feature request not found." };
 369→
 370→        await db.featureRequest.update({
 371→          where: { id: statusId },
 372→          data: { status: newStatus },
 373→        });
 374→
 375→        return { success: true, intent: "update-status" };
 376→      }
 377→
 378→      default:
 379→        return { error: "Unknown action." };
 380→    }
 381→  } catch (err) {
 382→    const message =
 383→      err instanceof Error ? err.message : "An unexpected error occurred.";
 384→    return { error: message };
 385→  }
 386→};
