 821→                    <Text as="p" variant="bodySm" tone="subdued">requests</Text>
 822→                  </InlineStack>
 823→                </BlockStack>
 824→                <div style={{ width: "1px", height: "32px", background: "var(--p-color-border)" }} />
 825→                <InlineStack gap="400" wrap>
 826→                  <InlineStack gap="150" blockAlign="center">
 827→                    <div style={{ width: "8px", height: "8px", borderRadius: "50%", background: "#f59e0b", flexShrink: 0 }} />
 828→                    <Text as="p" variant="bodySm" tone="subdued">Under Review</Text>
 829→                    <Badge tone="attention">{String(stats.under_review)}</Badge>
