                      >
                        <Box
                          padding="400"
                          background="bg-surface"
                          borderWidth="025"
                          borderColor="border"
                          borderRadius="200"
                        >
                          <InlineStack
                            gap="400"
                            align="start"
                            blockAlign="start"
                            wrap={false}
                          >
                            {/* Vote column */}
                            <div style={{ flexShrink: 0 }}>
                              <button
                                type="button"
                                onClick={() => handleVote(feature.id)}
                                disabled={
                                  pendingVoteId === feature.id &&
                                  voteFetcher.state !== "idle"
                                }
                                style={{
                                  display: "flex",
                                  flexDirection: "column",
                                  alignItems: "center",
                                  justifyContent: "center",
                                  gap: "4px",
                                  padding: "8px 12px",
                                  minWidth: "60px",
                                  border: `1px solid ${isVoted ? "#22c55e" : "var(--p-color-border)"}`,
                                  borderRadius: "8px",
                                  background: isVoted
                                    ? "var(--p-color-bg-surface-success)"
                                    : "var(--p-color-bg-surface-secondary)",
                                  cursor: "pointer",
                                  transition: "background 0.15s ease, border-color 0.15s ease",
                                  opacity:
                                    pendingVoteId === feature.id &&
                                    voteFetcher.state !== "idle"
                                      ? 0.6
                                      : 1,
                                }}
                                aria-label={isVoted ? "Remove vote" : "Vote for this feature"}
                              >
                                <span
                                  style={{
                                    color: isVoted
                                      ? "var(--p-color-text-success)"
                                      : "var(--p-color-text-subdued)",
                                    display: "flex",
                                    alignItems: "center",
                                  }}
                                >
                                  <ChevronUpIcon width={16} height={16} />
                                </span>
                                <Text
                                  as="p"
                                  variant="headingSm"
                                  fontWeight="bold"
                                  alignment="center"
                                  tone={isVoted ? "success" : undefined}
                                >
                                  {feature.votesCount}
                                </Text>
                                <Text
                                  as="p"
                                  variant="bodySm"
                                  alignment="center"
                                  tone={isVoted ? "success" : "subdued"}
                                >
                                  {isVoted ? "voted" : "vote"}
                                </Text>
                              </button>
                            </div>

                            {/* Content */}
                            <Box width="100%">
                              <BlockStack gap="200">
                                <InlineStack
                                  align="space-between"
                                  blockAlign="start"
                                  wrap
                                >
                                  <Text
                                    as="p"
                                    variant="headingSm"
                                    fontWeight="semibold"
                                  >
                                    {feature.title}
                                  </Text>
                                  {isAdmin ? (
                                    <Box minWidth="140px">
                                      <Select
                                        label="Status"
                                        labelHidden
                                        options={STATUS_OPTIONS}
                                        value={feature.status}
                                        onChange={(val) =>
                                          handleStatusChange(feature.id, val)
                                        }
                                      />
                                    </Box>
                                  ) : (
                                    <Badge
                                      tone={STATUS_TONES[feature.status]}
                                    >
                                      {STATUS_LABELS[feature.status] ??
                                        feature.status}
                                    </Badge>
                                  )}
                                </InlineStack>

                                <Text as="p" tone="subdued" variant="bodySm">
                                  {displayDescription}
                                </Text>

                                <InlineStack
                                  align="space-between"
                                  blockAlign="center"
                                  wrap
                                >
                                  <InlineStack gap="200" blockAlign="center" wrap>
                                    <Badge>{feature.category}</Badge>
                                    {isOwner && <Badge tone="info">Yours</Badge>}
                                    <Text
                                      as="p"
                                      tone="subdued"
                                      variant="bodySm"
                                    >
                                      {formatDate(feature.createdAt)}
                                    </Text>
                                    {canEdit && (
                                      <Button
                                        variant="plain"
                                        size="slim"
                                        icon={EditIcon}
                                        onClick={() => handleOpenEdit(feature)}
                                        accessibilityLabel="Edit feature request"
                                      >
                                        Edit
                                      </Button>
                                    )}
                                    {canDelete && (
                                      <Button
                                        variant="plain"
                                        tone="critical"
                                        size="slim"
                                        icon={DeleteIcon}
                                        onClick={() =>
                                          handleDelete(feature.id)
                                        }
                                        loading={
                                          pendingDeleteId === feature.id &&
                                          deleteFetcher.state !== "idle"
                                        }
                                        accessibilityLabel="Delete feature request"
                                      >
                                        Delete
                                      </Button>
                                    )}
                                  </InlineStack>
                                  {needsTruncation && (
                                    <Button
                                      variant="plain"
                                      size="slim"
                                      onClick={() =>
                                        handleToggleExpand(feature.id)
                                      }
                                    >
                                      {isExpanded
                                        ? "Show less"
                                        : "View details \u2192"}
                                    </Button>
                                  )}
                                </InlineStack>
                              </BlockStack>
                            </Box>
                          </InlineStack>
                        </Box>
                      </div>
                    );
                  })}
                </BlockStack>
              )}
              </Box>

              {/* Pagination */}
              {totalPages > 1 && (
                <>
                  <Divider />
                  <Box padding="400">
                    <InlineStack align="center" blockAlign="center">
                      <BlockStack gap="200" inlineAlign="center">
                        <Pagination
                          hasPrevious={currentPage > 1}
                          onPrevious={() => setCurrentPage((p) => Math.max(1, p - 1))}
                          hasNext={currentPage < totalPages}
                          onNext={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                          label={`Page ${currentPage} of ${totalPages}`}
                        />
                        <Text as="p" tone="subdued" variant="bodySm" alignment="center">
                          {filteredFeatures.length} requests total
                        </Text>
                      </BlockStack>
                    </InlineStack>
                  </Box>
                </>
              )}
            </Card>
          </Layout.Section>

        </Layout>
      </Box>

      {/* ---- Suggest a Feature Modal ---- */}
      <Modal
        open={modalOpen}
        onClose={handleCloseModal}
        title="Suggest a Feature"
        primaryAction={{
          content: "Submit Request",
          onAction: handleSubmitFeature,
          loading: submitFetcher.state !== "idle",
        }}
        secondaryActions={[{ content: "Cancel", onAction: handleCloseModal }]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {modalError && (
              <Banner tone="critical" onDismiss={() => setModalError(null)}>
                {modalError}
              </Banner>
            )}
            <TextField
              label="Title"
              value={newTitle}
              onChange={setNewTitle}
              placeholder="e.g. Export ZIP codes to CSV"
              autoComplete="off"
              maxLength={150}
              showCharacterCount
              helpText="Keep it short and descriptive."
            />
            <TextField
              label="Description"
              value={newDescription}
              onChange={setNewDescription}
              placeholder="Describe the feature and why it would be valuable..."
              autoComplete="off"
              multiline={4}
              maxLength={MAX_DESCRIPTION_LENGTH}
              showCharacterCount
              helpText="The more context you provide, the better we can understand your needs."
            />
            <Select
              label="Category"
              options={CATEGORY_OPTIONS}
              value={newCategory}
              onChange={setNewCategory}
              helpText="Choose the category that best fits your request."
            />
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* ---- Edit Feature Request Modal ---- */}
      <Modal
        open={editModalOpen}
        onClose={handleCloseEditModal}
        title="Edit Feature Request"
        primaryAction={{
          content: "Save Changes",
          onAction: handleEditSubmit,
          loading: editFetcher.state !== "idle",
        }}
        secondaryActions={[{ content: "Cancel", onAction: handleCloseEditModal }]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {editModalError && (
              <Banner tone="critical" onDismiss={() => setEditModalError(null)}>
                {editModalError}
              </Banner>
            )}
            <TextField
              label="Title"
              value={editTitle}
              onChange={setEditTitle}
              placeholder="e.g. Export ZIP codes to CSV"
              autoComplete="off"
              maxLength={150}
              showCharacterCount
              helpText="Keep it short and descriptive."
            />
            <TextField
              label="Description"
              value={editDescription}
              onChange={setEditDescription}
              placeholder="Describe the feature and why it would be valuable..."
              autoComplete="off"
              multiline={4}
              maxLength={MAX_DESCRIPTION_LENGTH}
              showCharacterCount
              helpText="The more context you provide, the better we can understand your needs."
            />
            <Select
              label="Category"
              options={CATEGORY_OPTIONS}
              value={editCategory}
              onChange={setEditCategory}
              helpText="Choose the category that best fits your request."
            />
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export function ErrorBoundary() {
  return boundary.error(useRouteError());
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

