566→            }
567→            if (cfg.showZone && data.zone) {
568→              html += '<div class="zcc-meta">' + ICONS.location + '<span>Zone: <strong>' + esc(data.zone) + '</strong></span></div>';
569→            }
570→            if (cfg.showDeliveryDays && data.daysOfWeek) {
571→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
572→              html += '<div class="zcc-meta zcc-days">' + ICONS.calendar + '<span>' + esc(days) + '</span></div>';
573→            }
574→            if (cfg.showCutoffTime && data.cutoffTime) {
