606→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button"><span class="zcc-wl-btn-icon">' + ICONS.mail + '</span><span class="zcc-wl-btn-label">Submit Request</span></button>' +
607→                '</div>' +
608→                '</div>';
609→            }
610→            html += '</div></div>';
611→            res.innerHTML = html;
612→
613→            if (cfg.showWaitlistOnFailure) {
