652→              }
653→            }
654→          }
655→
656→          // Block/unblock Add to Cart based on result (if merchant enabled this)
657→          if (cfg.blockCartOnInvalid) {
658→            var ATC_SELECTORS = [
659→              'button[name="add"]',
660→              '.product-form__submit',
661→              '[data-product-add]',
662→              '.btn--add-to-cart',
663→              '.product-form button[type="submit"]',
664→              'button.shopify-payment-button__button',
665→              '.shopify-payment-button button',
666→              'button.product-form__cart-submit'
667→            ].join(',');
668→
669→            try {
670→              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
671→              atcBtns.forEach(function(b) {
672→                if (!b.closest('#zcc-widget, [data-zcc-widget]')) { // Don't touch our own widget's button
673→                  if (data.allowed) {
