                    {/* Meta rows */}
                    <div style={{ display: "flex", flexDirection: "column", gap: 4, paddingLeft: 52 }}>
                      <div style={{ fontSize: 12, color: "#8c8c8c", fontFamily: "system-ui" }}>
                        <span style={{ color: "#6b6b6b" }}>To:</span>{" "}
