 899→const PositionTile = memo(function PositionTile({
 900→  value,
 901→  label,
 902→  selected,
 903→  disabled,
 904→  onSelect,
 905→  children,
 906→}: {
 907→  value: string;
 908→  label: string;
 909→  selected: boolean;
 910→  disabled: boolean;
 911→  onSelect: (v: string) => void;
 912→  children: React.ReactNode;
 913→}) {
 914→  const handleClick = useCallback(() => {
 915→    if (!disabled) onSelect(value);
 916→  }, [disabled, onSelect, value]);
 917→
 918→  return (
 919→    <button
 920→      type="button"
 921→      aria-pressed={selected}
 922→      onClick={handleClick}
 923→      disabled={disabled}
 924→      onKeyDown={(e) => {
