                      {/* Body content */}
                      <div style={{ padding: "24px 28px" }}>
                        <p style={{ margin: "0 0 20px", fontSize: 15, lineHeight: 1.7, color: "#374151" }}>
                          Hi there! Thanks for signing up. We&apos;ll notify you as soon as
                          delivery is available to your area.
