 668→              'button.shopify-payment-button__button',
 669→              '.shopify-payment-button button',
 670→              'button.product-form__cart-submit'
 671→            ].join(',');
 672→
 673→            try {
 674→              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
 675→              atcBtns.forEach(function(b) {
 676→                if (!b.closest('#zcc-widget, [data-zcc-widget]')) { // Don't touch our own widget's button
 677→                  if (data.allowed) {
 678→                    b.disabled = false;
