 725→          // changes (any change away from the verified value is unverified).
 726→          if (lastValid && lastValidZip) {
 727→            var currentVal = normalizeZip(inp.value);
 728→            if (currentVal !== lastValidZip) {
 729→              // Mark as unverified immediately
 730→              sessionStorage.setItem('zcc:valid', 'false');
 731→              sessionStorage.removeItem('zcc:zip');
 732→              // Re-block ATC buttons until the new ZIP is verified
 733→              var ATC_SELECTORS = [
 734→                'button[name="add"]',
 735→                '.product-form__submit',
 736→                '[data-product-add]',
 737→                '.btn--add-to-cart',
 738→                '.product-form button[type="submit"]',
 739→                'button.shopify-payment-button__button',
 740→                '.shopify-payment-button button',
 741→                'button.product-form__cart-submit'
 742→              ].join(',');
 743→              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
 744→              atcBtns.forEach(function(b) {
 745→                if (!b.closest('[data-zcc-widget]')) {
 746→                  if (!b.getAttribute('data-zcc-blocked')) {
 747→                    b.setAttribute('data-zcc-orig-title', b.title || '');
 748→                  }
 749→                  b.disabled = true;
 750→                  b.style.opacity = '0.5';
 751→                  b.title = 'Please check ZIP code availability first';
 752→                  b.setAttribute('data-zcc-blocked', 'true');
 753→                }
 754→              });
 755→            }
 756→          }
 757→          // If the last check was NOT successful (buttons are already blocked),
 758→          // do nothing — clearing or changing the input must never unblock buttons.
 759→        } catch(e) {}
 760→      });
 761→    }
