 764→  function joinWaitlist(zip, email, name, wBtn) {
 765→    // Store original button HTML so we can restore it exactly (same pattern as setBtnLoading)
 766→    var wBtnOriginalHtml = wBtn.innerHTML;
 767→
 768→    wBtn.disabled = true;
 769→    wBtn.classList.add('zcc-btn--loading');
 770→    wBtn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
 771→
 772→    var payload = { shop: SHOP, zip: zip, email: email };
 773→    if (name) payload.name = name;
 774→
 775→    function restoreBtn() {
 776→      wBtn.disabled = false;
 777→      wBtn.classList.remove('zcc-btn--loading');
 778→      wBtn.innerHTML = wBtnOriginalHtml;
 779→    }
 780→
 781→    fetch(API_BASE + "/api/waitlist", {
 782→      method: "POST",
 783→      headers: { "Content-Type": "application/json" },
 784→      body: JSON.stringify(payload),
 785→    })
 786→      .then(function (r) { return r.json(); })
 787→      .then(function (data) {
 788→        var wlEl = wBtn.closest(".zcc-wl");
