 664→const WidgetPreview = memo(function WidgetPreview({
 665→  cfg,
 666→  previewState,
 667→  widgetFullCustom,
 668→  showEtaCodReturn,
 669→}: {
 670→  cfg: WidgetConfig;
 671→  previewState: "idle" | "success" | "error" | "notfound";
 672→  widgetFullCustom: boolean;
 673→  showEtaCodReturn: boolean;
 674→}) {
 675→  const wid = "zcc-admin-preview";
 676→
 677→  // Apply the same plan enforcement the API applies so the preview matches
 678→  // exactly what will render on the storefront.
 679→  const effectiveCfg: WidgetConfig = useMemo(() => {
 680→    const c = { ...cfg };
 681→    if (!widgetFullCustom) {
 682→      c.primaryColor = DEFAULTS.primaryColor;
 683→      c.successColor = DEFAULTS.successColor;
 684→      c.errorColor = DEFAULTS.errorColor;
 685→      c.backgroundColor = DEFAULTS.backgroundColor;
 686→      c.textColor = DEFAULTS.textColor;
 687→      c.position = DEFAULTS.position;
 688→    }
 689→    if (!showEtaCodReturn) {
 690→      c.showEta = false;
 691→      c.showZone = false;
 692→      c.showCod = false;
 693→      c.showReturnPolicy = false;
 694→      c.showCutoffTime = false;
 695→      c.showDeliveryDays = false;
 696→    }
 697→    return c;
 698→  }, [cfg, widgetFullCustom, showEtaCodReturn]);
 699→
 700→  const css = useMemo(() => buildWidgetCss(wid, effectiveCfg), [wid, effectiveCfg]);
 701→
 702→  const resultMessage =
 703→    previewState === "success" ? cfg.successMessage :
 704→    previewState === "error" ? cfg.errorMessage :
 705→    previewState === "notfound" ? cfg.notFoundMessage : null;
 706→
 707→  // SVG icons as inline JSX — consistent outlined/stroke style
 708→  // Use effectiveCfg for colors so the preview matches what storefront serves
 709→  const iconStyle = { width: 16, height: 16, display: "block" as const };
 710→  const metaIconStyle = { width: 14, height: 14, display: "block" as const, opacity: 0.7 };
 711→  const pinIcon = (
 712→    <svg viewBox="0 0 24 24" fill="none" stroke={effectiveCfg.primaryColor} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={iconStyle}>
 713→      <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/>
 714→    </svg>
