 656→              }
 657→            }
 658→          }
 659→
 660→          // Block/unblock Add to Cart based on result (if merchant enabled this)
 661→          if (cfg.blockCartOnInvalid) {
 662→            var ATC_SELECTORS = [
 663→              'button[name="add"]',
 664→              '.product-form__submit',
 665→              '[data-product-add]',
 666→              '.btn--add-to-cart',
