 683→                  } else {
 684→                    b.setAttribute('data-zcc-orig-title', b.title || '');
 685→                    b.disabled = true;
 686→                    b.style.opacity = '0.5';
 687→                    b.title = 'Please enter a valid ZIP code to continue';
 688→                    b.setAttribute('data-zcc-blocked', 'true');
 689→                  }
 690→                }
 691→              });
 692→            } catch(e) { /* DOM query may fail in some contexts */ }
 693→          }
 694→        })
 695→        .catch(function (err) {
 696→          setBtnLoading(false);
 697→          // Log to console so merchants/developers can diagnose API connectivity issues.
 698→          // The URL is logged so we can immediately see if the proxy/API base is wrong.
 699→          console.error('[Pinzo] ZIP check failed. API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"', err);
 700→          res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
 701→          try {
 702→            sessionStorage.removeItem('zcc:valid');
 703→            sessionStorage.removeItem('zcc:zip');
 704→            window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
