                {/* Layout — Position Only */}
                <Card>
                  <BlockStack gap="300">
                    <InlineStack align="space-between" blockAlign="center">
                      <Text as="h2" variant="headingMd">Layout</Text>
                      {!limits.widgetFullCustom && (
                        <Badge tone="info">Starter+</Badge>
