208→
209→    // If blockCartOnInvalid is enabled, disable ATC/Buy Now buttons on page load
210→    // until the customer validates their ZIP code
211→    if (cfg.blockCartOnInvalid) {
212→      blockCartButtonsInitial();
213→    }
