567→  function wireWidget(wid, cfg, API_BASE, SHOP) {
568→    var inp = document.getElementById(wid + "-inp");
569→    var btn = document.getElementById(wid + "-btn");
570→    var res = document.getElementById(wid + "-res");
571→    if (!inp || !btn || !res) return;
572→
573→    function normalizeZip(raw) {
574→      var z = raw.trim().toUpperCase();
575→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
576→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
577→      return z;
578→    }
579→
580→    // Store the original button HTML so we can restore it exactly after loading
581→    var btnOriginalHtml = btn.innerHTML;
582→
583→    function setBtnLoading(loading) {
584→      btn.disabled = loading;
585→      if (loading) {
586→        btn.classList.add('zcc-btn--loading');
587→        // Replace entire button content with a lone spinner — no text overlap
588→        btn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
589→      } else {
590→        btn.classList.remove('zcc-btn--loading');
591→        // Restore original icon + label markup
592→        btn.innerHTML = btnOriginalHtml;
593→        // Keep button text in sync with config (merchant may have customised it)
594→        var labelEl = btn.querySelector('.zcc-btn-label');
595→        if (labelEl) labelEl.textContent = cfg.buttonText;
596→      }
597→    }
598→
599→    function checkZip() {
600→      var zip = normalizeZip(inp.value);
601→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
602→      if (!zip) { inp.focus(); return; }
603→
604→      setBtnLoading(true);
605→      res.innerHTML = "";
606→
607→      fetch(
608→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
609→          "&zip=" + encodeURIComponent(zip)
610→      )
611→        .then(function (r) {
612→          if (!r.ok) {
613→            // Non-2xx: try to parse JSON error body, fall back to status text
614→            return r.json().catch(function() {
615→              return { error: 'Server error (' + r.status + ')' };
616→            });
617→          }
618→          return r.json();
619→        })
620→        .then(function (data) {
621→          setBtnLoading(false);
622→
623→          // If the API returned an error object (no allowed field), treat as a
624→          // transient server error and show it in the result area rather than
625→          // falling through with undefined message text.
626→          if (data.error && data.allowed === undefined) {
627→            console.error('[Pinzo] API returned error:', data.error, '| API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"');
628→            res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
629→            try {
630→              sessionStorage.removeItem('zcc:valid');
631→              sessionStorage.removeItem('zcc:zip');
632→              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
633→            } catch(e) {}
634→            return;
635→          }
636→
637→          // Store validation result for cart page
638→          try {
639→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
640→            sessionStorage.setItem('zcc:zip', zip);
641→            sessionStorage.setItem('zcc:shop', SHOP);
642→            // Fire custom event for other scripts to listen to
643→            window.dispatchEvent(new CustomEvent('zcc:validated', {
644→              detail: { valid: data.allowed, zip: zip }
645→            }));
646→          } catch(e) { /* sessionStorage may be unavailable */ }
647→
648→          if (data.allowed) {
649→            var html = '<div class="zcc-result ok">' +
650→              '<div class="zcc-result-icon">' + ICONS.check + '</div>' +
651→              '<div class="zcc-result-content">' +
652→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
653→            if (cfg.showEta && data.eta) {
654→              html += '<div class="zcc-meta">' + ICONS.truck + '<span>Estimated delivery: <strong>' + esc(data.eta) + '</strong></span></div>';
655→            }
656→            // Delivery Date
657→            if (cfg.showDeliveryDate && data.estimatedDeliveryDate) {
658→              var dateStr = formatDeliveryDate(data.estimatedDeliveryDate);
659→              if (dateStr) {
660→                html += '<div class="zcc-meta zcc-delivery-date">' + ICONS.calendar + '<span>Expected by <strong>' + esc(dateStr) + '</strong></span></div>';
661→              }
662→            }
663→            if (cfg.showZone && data.zone) {
664→              html += '<div class="zcc-meta">' + ICONS.location + '<span>Zone: <strong>' + esc(data.zone) + '</strong></span></div>';
665→            }
666→            if (cfg.showDeliveryDays && data.daysOfWeek) {
667→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
668→              html += '<div class="zcc-meta zcc-days">' + ICONS.calendar + '<span>' + esc(days) + '</span></div>';
669→            }
670→            if (cfg.showCutoffTime && data.cutoffTime) {
671→              var parts = data.cutoffTime.split(':');
672→              var hr = parseInt(parts[0], 10);
673→              var min = parts[1] || '00';
674→              var ampm = hr >= 12 ? 'PM' : 'AM';
675→              var hr12 = hr % 12 || 12;
676→              html += '<div class="zcc-meta zcc-cutoff">' + ICONS.clock + '<span>Order by <strong>' + hr12 + ':' + min + ' ' + ampm + '</strong> for same-day</span></div>';
677→            }
678→            // Countdown Timer
679→            if (cfg.showCountdown && data.cutoffTime) {
680→              html += buildCountdownHtml(data.cutoffTime, wid);
681→            }
682→            if (cfg.showCod !== false) {
