 609→      fetch(
 610→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
 611→          "&zip=" + encodeURIComponent(zip)
 612→      )
 613→        .then(function (r) {
 614→          if (!r.ok) {
 615→            // Non-2xx: try to parse JSON error body, fall back to status text
 616→            return r.json().catch(function() {
 617→              return { error: 'Server error (' + r.status + ')' };
 618→            });
 619→          }
 620→          return r.json();
 621→        })
 622→        .then(function (data) {
