 838→          // If the last check was successful, re-block as soon as the input
 839→          // changes (any change away from the verified value is unverified).
 840→          if (lastValid && lastValidZip) {
 841→            var currentVal = normalizeZip(inp.value);
 842→            if (currentVal !== lastValidZip) {
 843→              // Mark as unverified immediately
 844→              sessionStorage.setItem('zcc:valid', 'false');
 845→              sessionStorage.removeItem('zcc:zip');
 846→              // Re-block ATC buttons until the new ZIP is verified
 847→              var ATC_SELECTORS = [
 848→                'button[name="add"]',
 849→                '.product-form__submit',
 850→                '[data-product-add]',
 851→                '.btn--add-to-cart',
 852→                '.product-form button[type="submit"]',
 853→                'button.shopify-payment-button__button',
 854→                '.shopify-payment-button button',
 855→                'button.product-form__cart-submit'
 856→              ].join(',');
 857→              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
 858→              atcBtns.forEach(function(b) {
 859→                if (!b.closest('[data-zcc-widget]')) {
 860→                  if (!b.getAttribute('data-zcc-blocked')) {
 861→                    b.setAttribute('data-zcc-orig-title', b.title || '');
 862→                  }
 863→                  b.disabled = true;
 864→                  b.style.opacity = '0.5';
 865→                  b.title = 'Please check ZIP code availability first';
 866→                  b.setAttribute('data-zcc-blocked', 'true');
 867→                }
 868→              });
 869→            }
 870→          }
 871→          // If the last check was NOT successful (buttons are already blocked),
 872→          // do nothing — clearing or changing the input must never unblock buttons.
 873→        } catch(e) {}
