 878→  function joinWaitlist(zip, email, name, wBtn) {
 879→    // Store original button HTML so we can restore it exactly (same pattern as setBtnLoading)
 880→    var wBtnOriginalHtml = wBtn.innerHTML;
 881→
 882→    wBtn.disabled = true;
 883→    wBtn.classList.add('zcc-btn--loading');
 884→    wBtn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
 885→
 886→    var payload = { shop: SHOP, zip: zip, email: email };
 887→    if (name) payload.name = name;
 888→
 889→    function restoreBtn() {
 890→      wBtn.disabled = false;
 891→      wBtn.classList.remove('zcc-btn--loading');
 892→      wBtn.innerHTML = wBtnOriginalHtml;
 893→    }
 894→
 895→    fetch(API_BASE + "/api/waitlist", {
 896→      method: "POST",
 897→      headers: { "Content-Type": "application/json" },
 898→      body: JSON.stringify(payload),
 899→    })
 900→      .then(function (r) { return r.json(); })
 901→      .then(function (data) {
 902→        var wlEl = wBtn.closest(".zcc-wl");
 903→        if (data.success) {
 904→          if (wlEl) wlEl.innerHTML =
 905→            '<div class="zcc-wl-success">' +
 906→            '<span class="zcc-wl-success-icon">' + ICONS.checkmark + '</span>' +
 907→            '<span>Your request has been submitted! We\u2019ll notify you when delivery is available.</span>' +
 908→            '</div>';
 909→        } else {
 910→          restoreBtn();
 911→        }
 912→      })
 913→      .catch(function () {
 914→        restoreBtn();
 915→      });
 916→  }
