  }

  // Popup position: realistic modal overlay simulation
  if (effectiveCfg.position === "popup") {
    return (
      <PopupPreview cfg={effectiveCfg} css={css} wid={wid} widgetHtml={widgetHtml} pinIcon={pinIcon} />
