    fd.set("showDeliveryDays", String(showDeliveryDays));
    fd.set("showDeliveryDate", String(showDeliveryDate));
    fd.set("showCountdown", String(showCountdown));
    fd.set("showDeliveryFee", String(showDeliveryFee));
