                    )}

                    {/* Preview widget — device frame + dot-grid */}
                    <div style={{
                      border: "1px solid #e2e8f0",
                      borderRadius: 12,
                      overflow: "hidden",
                      background: "#fff",
                    }}>
                      {/* Browser chrome */}
                      <div style={{
                        height: 32,
                        background: "#f8fafc",
                        borderBottom: "1px solid #e2e8f0",
                        display: "flex",
                        alignItems: "center",
