 569→  function wireWidget(wid, cfg, API_BASE, SHOP) {
 570→    var inp = document.getElementById(wid + "-inp");
 571→    var btn = document.getElementById(wid + "-btn");
 572→    var res = document.getElementById(wid + "-res");
 573→    if (!inp || !btn || !res) return;
 574→
 575→    function normalizeZip(raw) {
 576→      var z = raw.trim().toUpperCase();
 577→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
 578→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
 579→      return z;
 580→    }
 581→
 582→    // Store the original button HTML so we can restore it exactly after loading
 583→    var btnOriginalHtml = btn.innerHTML;
 584→
 585→    function setBtnLoading(loading) {
 586→      btn.disabled = loading;
 587→      if (loading) {
 588→        btn.classList.add('zcc-btn--loading');
 589→        // Replace entire button content with a lone spinner — no text overlap
 590→        btn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
 591→      } else {
 592→        btn.classList.remove('zcc-btn--loading');
 593→        // Restore original icon + label markup
 594→        btn.innerHTML = btnOriginalHtml;
 595→        // Keep button text in sync with config (merchant may have customised it)
 596→        var labelEl = btn.querySelector('.zcc-btn-label');
 597→        if (labelEl) labelEl.textContent = cfg.buttonText;
 598→      }
 599→    }
 600→
 601→    function checkZip() {
 602→      var zip = normalizeZip(inp.value);
 603→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
 604→      if (!zip) { inp.focus(); return; }
 605→
 606→      setBtnLoading(true);
 607→      res.innerHTML = "";
 608→
 609→      fetch(
 610→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
 611→          "&zip=" + encodeURIComponent(zip)
 612→      )
 613→        .then(function (r) {
 614→          if (!r.ok) {
 615→            // Non-2xx: try to parse JSON error body, fall back to status text
 616→            return r.json().catch(function() {
 617→              return { error: 'Server error (' + r.status + ')' };
 618→            });
 619→          }
 620→          return r.json();
 621→        })
 622→        .then(function (data) {
 623→          setBtnLoading(false);
 624→
 625→          // If the API returned an error object (no allowed field), treat as a
 626→          // transient server error and show it in the result area rather than
 627→          // falling through with undefined message text.
 628→          if (data.error && data.allowed === undefined) {
 629→            console.error('[Pinzo] API returned error:', data.error, '| API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"');
 630→            res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
 631→            try {
 632→              sessionStorage.removeItem('zcc:valid');
 633→              sessionStorage.removeItem('zcc:zip');
 634→              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
 635→            } catch(e) {}
 636→            return;
 637→          }
 638→
 639→          // Store validation result for cart page
 640→          try {
 641→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
 642→            sessionStorage.setItem('zcc:zip', zip);
 643→            sessionStorage.setItem('zcc:shop', SHOP);
 644→            // Fire custom event for other scripts to listen to
 645→            window.dispatchEvent(new CustomEvent('zcc:validated', {
 646→              detail: { valid: data.allowed, zip: zip }
 647→            }));
 648→          } catch(e) { /* sessionStorage may be unavailable */ }
 649→
 650→          if (data.allowed) {
 651→            var html = '<div class="zcc-result ok">' +
 652→              '<div class="zcc-result-icon">' + ICONS.check + '</div>' +
 653→              '<div class="zcc-result-content">' +
 654→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
 655→            if (cfg.showEta && data.eta) {
 656→              html += '<div class="zcc-meta">' + ICONS.truck + '<span>Estimated delivery: <strong>' + esc(data.eta) + '</strong></span></div>';
 657→            }
 658→            // Delivery Date
 659→            if (cfg.showDeliveryDate && data.estimatedDeliveryDate) {
 660→              var dateStr = formatDeliveryDate(data.estimatedDeliveryDate);
 661→              if (dateStr) {
 662→                html += '<div class="zcc-meta zcc-delivery-date">' + ICONS.calendar + '<span>Expected by <strong>' + esc(dateStr) + '</strong></span></div>';
 663→              }
 664→            }
 665→            if (cfg.showZone && data.zone) {
 666→              html += '<div class="zcc-meta">' + ICONS.location + '<span>Zone: <strong>' + esc(data.zone) + '</strong></span></div>';
 667→            }
 668→            if (cfg.showDeliveryDays && data.daysOfWeek) {
 669→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
 670→              html += '<div class="zcc-meta zcc-days">' + ICONS.calendar + '<span>' + esc(days) + '</span></div>';
 671→            }
