    const c = { ...cfg };
    if (!widgetFullCustom) {
      c.primaryColor = DEFAULTS.primaryColor;
      c.successColor = DEFAULTS.successColor;
      c.errorColor = DEFAULTS.errorColor;
      c.backgroundColor = DEFAULTS.backgroundColor;
      c.textColor = DEFAULTS.textColor;
