    setShowCutoffTime(DEFAULTS.showCutoffTime);
    setShowDeliveryDays(DEFAULTS.showDeliveryDays);
    setShowDeliveryDate(DEFAULTS.showDeliveryDate);
    setShowCountdown(DEFAULTS.showCountdown);
