 419→    W + " .zcc-result.fail .zcc-result-icon svg{color:" + e + ";stroke:" + e + "}" +
 420→    W + " .zcc-wl{margin-top:10px;padding:13px 14px;background:#f8fafc;border-radius:10px;border:1px solid #e2e8f0}" +
 421→    W + " .zcc-wl-input{border-radius:8px;border:1.5px solid #dee2e6;padding:10px 14px;width:100%;display:block;margin-bottom:8px;outline:none;font-size:13px;transition:border-color 0.2s,box-shadow 0.2s;background:#fff;color:" + cfg.textColor + "}" +
