 914→// ── Reusable position tile selector ─────────────────────────────────────────
 915→const PositionTile = memo(function PositionTile({
 916→  value,
 917→  label,
 918→  selected,
 919→  disabled,
 920→  onSelect,
 921→  children,
 922→}: {
 923→  value: string;
